function(container, apiUrl, tables) {
  const questionsList = container.querySelector('#questions-list');
  const detailPanel = container.querySelector('#detail-panel');
  const emptyState = container.querySelector('#empty-state');
  const questionTitle = container.querySelector('#question-title');
  const questionContent = container.querySelector('#question-content');
  const answerText = container.querySelector('#answer-text');
  const answerStatus = container.querySelector('#answer-status');
  const materialsList = container.querySelector('#materials-list');
  const uploadZone = container.querySelector('#upload-zone');
  const fileInput = container.querySelector('#file-input');
  const btnSelectFile = container.querySelector('#btn-select-file');
  const btnSaveDraft = container.querySelector('#btn-save-draft');
  const btnPublishAnswer = container.querySelector('#btn-publish-answer');
  const btnBackToList = container.querySelector('#btn-back-to-list');
  const searchInput = container.querySelector('[data-testid="question-search"]');
  const previewModal = container.querySelector('#preview-modal');
  const previewTitle = container.querySelector('#preview-title');
  const previewContent = container.querySelector('#preview-content');
  const btnClosePreview = container.querySelector('#btn-close-preview');
  const contractLink = container.querySelector('#contract-link');
  const proposalLink = container.querySelector('#proposal-link');

  let currentQuestionId = null;
  let allQuestions = [];
  let questionAnswers = {}; // { questionId: { answer, materials, status } }
  let uploadedFiles = []; // 現在のセッションでアップロードされたファイル

  // 質問データ取得（テーブルインデックス 0 を想定）
  async function loadQuestions() {
    const questions = await window.aivicApi.list(0);
    if (!questions) return;
    allQuestions = questions;
    renderQuestionsList(questions);
  }

  // 質問一覧を描画
  function renderQuestionsList(questions) {
    questionsList.innerHTML = '';
    questions.forEach(q => {
      const item = document.createElement('div');
      item.className = 'question-item';
      item.dataset.id = q.id;
      item.style.cssText = `
        padding: 10px 12px;
        margin-bottom: 6px;
        background: ${currentQuestionId === q.id ? 'rgba(255,165,0,0.15)' : 'transparent'};
        border-left: 3px solid ${currentQuestionId === q.id ? 'var(--primary)' : 'transparent'};
        border-radius: 4px;
        cursor: pointer;
        transition: all 0.2s;
        border: 1px solid ${currentQuestionId === q.id ? 'rgba(255,165,0,0.3)' : 'rgba(255,255,255,0.1)'};
      `;
      item.innerHTML = `
        <p style="margin: 0 0 4px 0; font-size: 12px; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.5px;">Q${questions.indexOf(q) + 1}</p>
        <p style="margin: 0; font-size: 13px; color: var(--text); line-height: 1.4; word-break: break-word;">${q.title || q.name || '無題'}</p>
      `;
      item.addEventListener('click', () => selectQuestion(q));
      questionsList.appendChild(item);
    });
  }

  // 質問を選択
  function selectQuestion(question) {
    currentQuestionId = question.id;
    uploadedFiles = [];
    detailPanel.style.display = 'block';
    emptyState.style.display = 'none';
    btnBackToList.style.display = 'inline-block';

    questionTitle.textContent = question.title || question.name || '無題';
    questionContent.textContent = question.description || question.content || '（説明なし）';

    // 既存の回答を取得
    if (questionAnswers[question.id]) {
      const saved = questionAnswers[question.id];
      answerText.value = saved.answer || '';
      answerStatus.textContent = `ステータス: ${saved.status || '未保存'}`;
      renderMaterials(saved.materials || []);
    } else {
      answerText.value = '';
      answerStatus.textContent = '';
      materialsList.innerHTML = '';
    }

    renderQuestionsList(allQuestions);
  }

  // 根拠資料を描画
  function renderMaterials(materials) {
    materialsList.innerHTML = '';
    materials.forEach((mat, idx) => {
      const matItem = document.createElement('div');
      matItem.style.cssText = `
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding: 8px;
        background: rgba(0,0,0,0.15);
        border-radius: 4px;
        margin-bottom: 6px;
        font-size: 12px;
      `;
      matItem.innerHTML = `
        <div style="flex: 1;">
          <p style="margin: 0 0 2px 0; color: var(--text);">📎 ${mat.name || `ファイル${idx + 1}`}</p>
          <p style="margin: 0; color: var(--text-muted); font-size: 11px;">${mat.size ? `${(mat.size / 1024).toFixed(1)} KB` : ''}</p>
        </div>
        <div style="display: flex; gap: 6px;">
          <button 
            class="preview-btn" 
            data-index="${idx}"
            data-testid="preview-material-btn"
            style="padding: 4px 8px; font-size: 11px; background: transparent; border: 1px solid rgba(255,255,255,0.18); color: var(--text); border-radius: 3px; cursor: pointer;"
          >
            👁️ プレビュー
          </button>
          <button 
            class="download-btn" 
            data-index="${idx}"
            data-testid="download-material-btn"
            style="padding: 4px 8px; font-size: 11px; background: transparent; border: 1px solid rgba(255,255,255,0.18); color: var(--text); border-radius: 3px; cursor: pointer;"
          >
            ⬇️ DL
          </button>
          <button 
            class="delete-btn" 
            data-index="${idx}"
            data-testid="delete-material-btn"
            style="padding: 4px 8px; font-size: 11px; background: transparent; border: 1px solid rgba(255,255,255,0.18); color: #ff6a6a; border-radius: 3px; cursor: pointer;"
          >
            🗑️
          </button>
        </div>
      `;
      materialsList.appendChild(matItem);
    });

    // イベントリスナー
    container.querySelectorAll('.preview-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const idx = parseInt(e.target.closest('.preview-btn').dataset.index);
        const mat = materials[idx];
        previewMaterial(mat);
      });
    });

    container.querySelectorAll('.download-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const idx = parseInt(e.target.closest('.download-btn').dataset.index);
        const mat = materials[idx];
        downloadMaterial(mat);
      });
    });

    container.querySelectorAll('.delete-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const idx = parseInt(e.target.closest('.delete-btn').dataset.index);
        deleteMaterial(idx);
      });
    });
  }

  // ファイルアップロード処理
  function setupFileUpload() {
    uploadZone.addEventListener('click', () => fileInput.click());
    uploadZone.addEventListener('dragover', (e) => {
      e.preventDefault();
      uploadZone.style.background = 'rgba(255,165,0,0.2)';
      uploadZone.style.borderColor = 'var(--primary)';
    });
    uploadZone.addEventListener('dragleave', () => {
      uploadZone.style.background = 'rgba(0,0,0,0.15)';
      uploadZone.style.borderColor = 'rgba(255,255,255,0.3)';
    });
    uploadZone.addEventListener('drop', (e) => {
      e.preventDefault();
      uploadZone.style.background = 'rgba(0,0,0,0.15)';
      uploadZone.style.borderColor = 'rgba(255,255,255,0.3)';
      handleFiles(e.dataTransfer.files);
    });

    fileInput.addEventListener('change', (e) => {
      handleFiles(e.target.files);
    });

    btnSelectFile.addEventListener('click', () => fileInput.click());
  }

  function handleFiles(files) {
    Array.from(files).forEach(file => {
      const reader = new FileReader();
      reader.onload = (e) => {
        uploadedFiles.push({
          name: file.name,
          size: file.size,
          type: file.type,
          data: e.target.result
        });
        updateMaterialsList();
      };
      reader.readAsArrayBuffer(file);
    });
  }

  function updateMaterialsList() {
    if (!currentQuestionId) return;
    if (!questionAnswers[currentQuestionId]) {
      questionAnswers[currentQuestionId] = { answer: '', materials: [], status: '未保存' };
    }
    questionAnswers[currentQuestionId].materials = uploadedFiles;
    renderMaterials(uploadedFiles);
  }

  function deleteMaterial(idx) {
    uploadedFiles.splice(idx, 1);
    updateMaterialsList();
  }

  function previewMaterial(material) {
    previewTitle.textContent = material.name;
    if (material.type.startsWith('image/')) {
      const img = document.createElement('img');
      img.src = URL.createObjectURL(new Blob([material.data], { type: material.type }));
      img.style.maxWidth = '100%';
      previewContent.innerHTML = '';
      previewContent.appendChild(img);
    } else if (material.type === 'application/pdf') {
      previewContent.innerHTML = '<p style="color: var(--text-muted);">PDF プレビューは別途表示します</p>';
    } else {
      previewContent.innerHTML = '<p style="color: var(--text-muted);">このファイル形式はプレビューできません</p>';
    }
    previewModal.style.display = 'flex';
  }

  function downloadMaterial(material) {
    const blob = new Blob([material.data], { type: material.type });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = material.name;
    a.click();
    URL.revokeObjectURL(url);
  }

  // 回答保存
  btnSaveDraft.addEventListener('click', async () => {
    if (!currentQuestionId) return;
    if (!questionAnswers[currentQuestionId]) {
      questionAnswers[currentQuestionId] = { answer: '', materials: [], status: '未保存' };
    }
    questionAnswers[currentQuestionId].answer = answerText.value;
    questionAnswers[currentQuestionId].status = '下書き保存';
    answerStatus.textContent = 'ステータス: 下書き保存 ✓';
    setTimeout(() => {
      answerStatus.textContent = '';
    }, 3000);
  });

  // 回答公開
  btnPublishAnswer.addEventListener('click', async () => {
    if (!currentQuestionId) return;
    if (!answerText.value.trim()) {
      alert('回答を入力してください');
      return;
    }
    if (!questionAnswers[currentQuestionId]) {
      questionAnswers[currentQuestionId] = { answer: '', materials: [], status: '未保存' };
    }
    questionAnswers[currentQuestionId].answer = answerText.value;
    questionAnswers[currentQuestionId].status = '公開済み';
    answerStatus.textContent = 'ステータス: 公開済み ✓';
    setTimeout(() => {
      answerStatus.textContent = '';
    }, 3000);
  });

  // 一覧に戻る
  btnBackToList.addEventListener('click', () => {
    currentQuestionId = null;
    detailPanel.style.display = 'none';
    emptyState.style.display = 'block';
    btnBackToList.style.display = 'none';
    uploadedFiles = [];
    renderQuestionsList(allQuestions);
  });

  // 検索
  searchInput.addEventListener('input', (e) => {
    const query = e.target.value.toLowerCase();
    const filtered = allQuestions.filter(q => 
      (q.title || q.name || '').toLowerCase().includes(query) ||
      (q.description || q.content || '').toLowerCase().includes(query)
    );
    renderQuestionsList(filtered);
  });

  // プレビューモーダル閉じる
  btnClosePreview.addEventListener('click', () => {
    previewModal.style.display = 'none';
  });
  previewModal.addEventListener('click', (e) => {
    if (e.target === previewModal) previewModal.style.display = 'none';
  });

  // 参照リンク
  contractLink.addEventListener('click', (e) => {
    e.preventDefault();
    alert('契約書を表示します（実装例）');
  });
  proposalLink.addEventListener('click', (e) => {
    e.preventDefault();
    alert('提案資料を表示します（実装例）');
  });

  // 初期化
  setupFileUpload();
  loadQuestions();
}
